28	  @Override
29	  public String getURL(Service service, String portName, String namespace, KubernetesClient client) {
30	    ServicePort port = URLFromServiceUtil.getServicePortByName(service, portName);
31	    String serviceName = service.getMetadata().getName();
32	    if (port == null) {
33	      throw new RuntimeException("Couldn't find port: " + portName + " for service " + service.getMetadata().getName());
34	    }
35	
36	    IngressList ingresses = client.extensions().ingresses().inNamespace(namespace).list();
37	    if (ingresses != null && !ingresses.getItems().isEmpty()) {
38	      return URLFromServiceUtil.getURLFromIngressList(ingresses.getItems(), namespace, serviceName, port);
39	    }
40	    return null;
41	  }
42	
